    #[tokio::test]
    async fn dav_auth_rate_limiter_blocks_after_max_attempts() {
        let db = TestDb::new().await;
        let key = SecretKey::generate();
        let accounts = CaldavAccountService::new_at(
            db.pool.clone(),
            key,
            url::Url::parse("http://127.0.0.1:3000").unwrap(),
